class User:
    def __init__(self, name): self.name = name
    @classmethod
    def from_email(cls, email): return cls(email.split('@')[0])
print(User.from_email('sam@example.com').name)

class Tax:
    @staticmethod
    def add_rate(amount, rate): return amount * (1 + rate)
print(Tax.add_rate(100, .1))

class Demo:
    def instance(self): return 'instance'
    @classmethod
    def klass(cls): return cls.__name__
    @staticmethod
    def utility(): return 'utility'
d = Demo()
print(d.instance(), d.klass(), d.utility())

class Greeter:
    def greet(self):
        return 'hello'
person = Greeter()
del Greeter.greet
try:
    person.greet()
except AttributeError:
    print('method removed')
